exercises.starter:
def checked_sqrt(x):
    # raise ValueError when x is negative; otherwise return its square root
    pass

exercises.solution:
def checked_sqrt(x):
    if x < 0:
        raise ValueError('x must be non-negative')
    return x ** 0.5

exercises.starter:
def safe_divide(a, b):
    # raise ValueError when b is 0; otherwise return a / b
    pass

exercises.solution:
def safe_divide(a, b):
    if b == 0:
        raise ValueError('cannot divide by zero')
    return a / b

exercises.starter:
def get_at(xs, i):
    # raise IndexError when i is out of range; otherwise return xs[i]
    pass

exercises.solution:
def get_at(xs, i):
    if i < 0 or i >= len(xs):
        raise IndexError('index out of range')
    return xs[i]

exercises.starter:
def parse_positive(n):
    # raise ValueError when n is zero or negative; otherwise return n
    pass

exercises.solution:
def parse_positive(n):
    if n <= 0:
        raise ValueError('n must be positive')
    return n

exercises.starter:
def require_int(x):
    # raise TypeError when x is not an int; otherwise return x
    pass

exercises.solution:
def require_int(x):
    if not isinstance(x, int):
        raise TypeError('expected an int')
    return x
